import math
S={'x':0.0,'y':0.0,'th':0.0,'corners':[],'af':0.0,'u':None,'fwd':False,'n':0,'stopwoke':False,'mode':'gap'}
R=math.radians
D=math.degrees
def wrap(a):
    while a>math.pi: a-=2*math.pi
    while a<-math.pi: a+=2*math.pi
    return a
def gap_dir(pts):
    hw=1.05
    angs=list(range(-60,61,3))
    fr=[]
    for a in angs:
        c=math.cos(R(a)); s=math.sin(R(a)); f=9.0
        for X,Y in pts:
            al=X*c+Y*s
            if al<=0: continue
            pp=-X*s+Y*c
            if abs(pp)<hw:
                f=min(f,max(0.0,al-math.sqrt(hw*hw-pp*pp)))
        fr.append(f)
    mx=max(fr)
    thr=0.85*mx
    runs=[];cur=None
    for i,f in enumerate(fr):
        if f>=thr:
            if cur is None: cur=[i,i]
            else: cur[1]=i
        else:
            if cur: runs.append(cur); cur=None
    if cur: runs.append(cur)
    best=None;bs=-1
    for r in runs:
        sm=sum(fr[r[0]:r[1]+1])
        if sm>bs: bs=sm;best=r
    return 0.5*(angs[best[0]]+angs[best[1]]),mx
def control(obs):
    S['n']+=1
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion']; v=m['v_mps']; dl=R(obs['steer_deg'])
    th=S['th']
    S['x']+=v*math.cos(th)*dt; S['y']+=v*math.sin(th)*dt; S['th']+=v*math.tan(dl)/2.75*dt
    th=S['th']; c=math.cos(th); s=math.sin(th)
    def tow(p):
        return (S['x']+c*p[0]-s*p[1], S['y']+s*p[0]+c*p[1])
    rig=obs['rig']
    rx,ry=tow(rig['trailer_rear'])
    tb=th+R(180+rig['trailer_heading_deg'])
    ct=math.cos(tb); stt=math.sin(tb)
    def totr(w):
        dx=w[0]-rx; dy=w[1]-ry
        return (dx*ct+dy*stt, -dx*stt+dy*ct)
    views=obs.get('views') or {}
    for k,vw in views.items():
        try:
            o=vw['origin']
            for cn in vw.get('target_corners',[]) or []:
                b=cn[0]; dd=cn[1]
                w=tow((o[0]+dd*math.cos(R(b)), o[1]+dd*math.sin(R(b))))
                hit=False
                for q in S['corners']:
                    if math.hypot(q[0]-w[0],q[1]-w[1])<1.0:
                        q[0]=0.7*q[0]+0.3*w[0]; q[1]=0.7*q[1]+0.3*w[1]; q[2]+=1; hit=True; break
                if not hit: S['corners'].append([w[0],w[1],1])
        except Exception:
            pass
    cam=views.get('camera')
    phi=obs['hitch_deg']
    rem=obs.get('progress',{}).get('remaining',20)
    speed=-1.1 if rem>10 else -0.8
    a=None
    corners=sorted(S['corners'],key=lambda q:-q[2])[:4]
    if len(corners)>=4 and rem<10:
        S['mode']='bay'
        cx=sum(q[0] for q in corners)/4; cy=sum(q[1] for q in corners)/4
        sxx=sum((q[0]-cx)**2 for q in corners); syy=sum((q[1]-cy)**2 for q in corners); sxy=sum((q[0]-cx)*(q[1]-cy) for q in corners)
        ang=0.5*math.atan2(2*sxy,sxx-syy)
        ux=math.cos(ang); uy=math.sin(ang)
        if S['u'] is None:
            if ux*(cx-rx)+uy*(cy-ry)<0: ux=-ux; uy=-uy
            S['u']=(ux,uy)
        else:
            if ux*S['u'][0]+uy*S['u'][1]<0: ux=-ux; uy=-uy
            S['u']=(ux,uy)
        hl=max(abs((q[0]-cx)*ux+(q[1]-cy)*uy) for q in corners)
        beta=wrap(math.atan2(uy,ux)-tb)
        e=ux*(ry-cy)-uy*(rx-cx)
        a=D(beta-math.atan(e/1.2))
        a=max(-35,min(35,a))
        sb=(cx-rx)*ux+(cy-ry)*uy+hl
        speed=-max(0.35,min(0.9,0.35*sb))
        if sb<0.25:
            speed=0.0
            if not S['stopwoke']:
                S['stopwoke']=True
                try: wake('at bay back line but leg not ended; sb=%.2f phi=%.1f'%(sb,phi))
                except Exception: pass
        S['af']+=0.5*(a-S['af'])
    elif cam:
        S['mode']='gap'
        pts=[]
        o=cam['origin']
        for b,dd in cam.get('walls',[]) or []:
            pts.append(totr(tow((o[0]+dd*math.cos(R(b)), o[1]+dd*math.sin(R(b))))))
        if pts:
            a,mx=gap_dir(pts)
        else:
            a=0.0
        S['af']+=0.3*(a-S['af'])
    af=S['af']
    pdes=max(-28,min(28,1.2*af))
    if abs(phi)>15 and speed<-0.8: speed=-0.8
    if S['fwd'] or abs(phi)>40:
        S['fwd']=abs(phi)>8
        if S['fwd']:
            st=30 if phi>0 else -30
            return (st,0.8,rig.get('screen_gaze_deg') or -23)
    ff=D(math.atan(0.75*math.tan(R(pdes))))
    st=ff+1.5*(phi-pdes)
    st=max(-34,min(34,st))
    if S['n']%10==0:
        print('t=%.1f mode=%s rem=%.1f a=%.1f pdes=%.1f phi=%.1f st=%.1f v=%.2f nc=%d'%(obs['t'],S['mode'],rem,af,pdes,phi,st,v,len(S['corners'])))
    return (st,speed,rig.get('screen_gaze_deg') or -23)

