    steer=ff+2.0*(hitch-phi_des)
    if clL<0.6: steer+=30.0*(0.6-clL)
    if clR<0.6: steer-=30.0*(0.6-clR)
    steer=clamp(steer,45.0)
    if tick%15==0:
        print('t=%.1f e=%.0f fn=%.1f hitch=%.1f phd=%.1f st=%.1f mn=%.2f clL=%.2f clR=%.2f n=%d'%(t,e,best[2],hitch,phi_des,steer,mn,clL,clR,len(pts)))
