import math
X=0.0;Y=0.0;TH=0.0
MAP={}
C=None;Cw=0.0
mode='REV';fs=None
af=0.0
lastp=-10.0

def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi

def tw(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)

def clamp(v,a,b):
    return max(a,min(b,v))

def _ctrl(obs):
    global X,Y,TH,C,Cw,mode,fs,af,lastp
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion'];v=m['v_mps'];st=math.radians(obs['steer_deg'])
    th0=TH
    TH+=v*math.tan(st)/1.25*dt
    thm=(th0+TH)/2
    X+=v*math.cos(thm)*dt;Y+=v*math.sin(thm)*dt
    rig=obs['rig'];views=obs.get('views') or {}
    for nm in ('direct','periphery'):
        vw=views.get(nm)
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            if nm=='direct' and d>8.5: continue
            px=ox+d*math.cos(math.radians(b));py=oy+d*math.sin(math.radians(b))
            wp=tw(px,py)
            MAP[(round(wp[0]*10),round(wp[1]*10))]=wp
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        e=rig['eye'];b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        wp=tw(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
        w=1.0/max(d,1.0)
        if C is None:
            C=wp;Cw=w
        else:
            k=Cw*0.95
            C=((C[0]*k+wp[0]*w)/(k+w),(C[1]*k+wp[1]*w)/(k+w));Cw=k+w
    phi=obs['hitch_deg']
    R=tw(*rig['trailer_rear'])
    thT=TH+math.radians(rig['trailer_heading_deg'])
    pb=thT+math.pi
    pts=[p for p in MAP.values() if (p[0]-R[0])**2+(p[1]-R[1])**2<16]
    Lcap=2.5
    angs=list(range(-75,76,5));Ls=[]
    for a in angs:
        dd=pb+math.radians(a);dx=math.cos(dd);dy=math.sin(dd);L=Lcap
        for p in pts:
            rx=p[0]-R[0];ry=p[1]-R[1];al=rx*dx+ry*dy
            if al<=0 or al>=L: continue
            if abs(rx*dy-ry*dx)<0.5: L=al
        Ls.append(L)
    # wall straight behind
    dx=math.cos(pb);dy=math.sin(pb);Lb=9
    for p in pts:
        rx=p[0]-R[0];ry=p[1]-R[1];al=rx*dx+ry*dy
        if al>0 and abs(rx*dy-ry*dx)<0.45: Lb=min(Lb,al)
    free=[L>=Lcap-1e-6 for L in Ls]
    ivs=[];i=0
    while i<len(angs):
        if free[i]:
            j=i
            while j+1<len(angs) and free[j+1]: j+=1
            ivs.append((angs[i],angs[j]));i=j+1
        else: i+=1
    aC=None;dC=None
    if C is not None:
        dC=math.hypot(C[0]-R[0],C[1]-R[1])
        aC=math.degrees(wrap(math.atan2(C[1]-R[1],C[0]-R[0])-pb))
    if ivs:
        iv=None
        if aC is not None and dC<9:
            for lo,hi in ivs:
                if lo-5<=aC<=hi+5: iv=(lo,hi)
        if iv is None:
            iv=min(ivs,key=lambda q: 0 if q[0]<=af<=q[1] else min(abs(q[0]-af),abs(q[1]-af)))
        lo,hi=iv;mid=(lo+hi)/2.0
        if aC is not None and dC<9 and hi-lo>=20:
            at=clamp(aC,lo+10,hi-10)
            if dC<2.0: at=0.5*mid+0.5*at
        else:
            at=mid
    else:
        k=max(range(len(Ls)),key=lambda i:(Ls[i],-abs(angs[i]-af)))
        at=angs[k]
    af+=0.3*(at-af)
