    vf=rig.get('vehicle_front',1.5);vhw=rig.get('vehicle_half_width',0.525);thw=rig.get('trailer_half_width',0.475)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    cs=[tw(vf,vhw),tw(vf,-vhw),tw(vf-1.8,vhw),tw(vf-1.8,-vhw)]
    nx=-math.sin(thT);ny=math.cos(thT)
    Fr=(R[0]+math.cos(thT)*1.0,R[1]+math.sin(thT)*1.0)
    for P in (R,Fr):
        cs.append((P[0]+nx*thw,P[1]+ny*thw));cs.append((P[0]-nx*thw,P[1]-ny*thw))
    near=[p for p in MAP.values() if (p[0]-R[0])**2+(p[1]-R[1])**2<25]
    mind=9
    for c in cs:
        for p in near:
            d=(p[0]-c[0])**2+(p[1]-c[1])**2
            if d<mind: mind=d
    mind=math.sqrt(mind)
    st_=obs.get('status')
    if mode=='REV' and (abs(phi)>50 or st_=='JACKKNIFED'):
        mode='FWD';fs=(X,Y);print('recover fwd phi',round(phi,1))
    if mode=='FWD':
        steer=clamp(-0.5*phi,-25,25);spd=0.5
        if abs(phi)<12 or math.hypot(X-fs[0],Y-fs[1])>1.5:
            mode='REV'
        return (steer,spd,-168)
    phid=clamp(-1.2*af,-35,35)
    pr=math.radians(phi)
    deq=math.degrees(math.atan(1.25*math.sin(pr)/(0.85+0.3*math.cos(pr))))
    steer=clamp(deq+1.3*(phi-phid),-45,45)
    spd=-0.5
    if abs(phi)>30 or mind<0.35: spd=-0.3
    if mind<0.2: spd=-0.2
    if Lb<0.25:
        spd=0.0
    if obs['t']-lastp>2.0:
        lastp=obs['t']
        print('t%.1f X%.2f Y%.2f TH%.0f phi%.0f at%.0f af%.0f phid%.0f st%.0f mind%.2f Lb%.1f C%s ivs%s'%(obs['t'],X,Y,math.degrees(TH),phi,at,af,phid,steer,mind,Lb,None if C is None else (round(C[0],1),round(C[1],1)),ivs))
    return (steer,spd,-168)

def control(obs):
    try:
        return _ctrl(obs)
    except Exception as e:
        print('ERR',e)
        return (0.0,0.0,-168)

