import math
X=0.0;Y=0.0;TH=0.0
MAP={}
C=[-6.1,-5.1];Cw=0.3
AX=math.radians(-138)
mode='REV';fs=(0.0,0.0);lastp=-10.0
VF=1.55;VHW=0.525;THW=0.475
gl_next=0.0;glancing=True;gdw=0
for i in range(46):
    x=-2.0+i*0.1
    MAP[('s',i)]=(x,0.70-0.08*x)

def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def tw(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)
def clamp(v,a,b):
    return max(a,min(b,v))

def sim(x,y,th,thT,vs,sd,dist,n=4):
    ds=dist/n;tn=math.tan(math.radians(sd));out=[]
    for k in range(n):
        v=vs*ds;yaw=v*tn/1.25
        hvx=v*math.cos(th)+0.3*yaw*math.sin(th)
        hvy=v*math.sin(th)-0.3*yaw*math.cos(th)
        thT+=(-hvx*math.sin(thT)+hvy*math.cos(thT))/0.85
        thm=th+yaw/2
        x+=v*math.cos(thm);y+=v*math.sin(thm);th+=yaw
        out.append((x,y,th,thT))
    return out

def corners(x,y,th,thT):
    c=math.cos(th);s=math.sin(th)
    def w(px,py): return (x+c*px-s*py,y+s*px+c*py)
    pts=[w(VF,VHW),w(VF,-VHW),w(VF-1.8,VHW),w(VF-1.8,-VHW),w(VF,0),w(VF-0.9,VHW),w(VF-0.9,-VHW)]
    hx,hy=w(-0.3,0)
    ct=math.cos(thT);st=math.sin(thT)
    ax=hx-0.85*ct;ay=hy-0.85*st
    for l in (0.55,-0.45):
        for sd in (THW,-THW):
            pts.append((ax+l*ct-sd*st,ay+l*st+sd*ct))
    pts.append((ax-0.45*ct,ay-0.45*st))
    return pts

def clear(state,near):
    m=9.0
    for c in corners(*state):
        for p in near:
            d=(p[0]-c[0])**2+(p[1]-c[1])**2
            if d<m: m=d
    return math.sqrt(m)

def choose(state,near,vs,sdes):
    cands=sorted(set([int(round(sdes))]+list(range(-40,41,5))))
    best=None
    for s in cands:
        tr=sim(state[0],state[1],state[2],state[3],vs,s,0.4)
        mc=min(clear(q,near) for q in tr)
        cost=abs(s-sdes)*0.02+10*max(0.0,0.15-mc)
        if best is None or cost<best[0]: best=(cost,s,mc)
    return best

def _ctrl(obs):
    global X,Y,TH,C,Cw,mode,fs,lastp,VF,VHW,THW,gl_next,glancing,gdw
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion'];v=m['v_mps'];st=math.radians(obs['steer_deg'])
    th0=TH
    TH+=v*math.tan(st)/1.25*dt
    thm=(th0+TH)/2
    X+=v*math.cos(thm)*dt;Y+=v*math.sin(thm)*dt
