    if isinstance(vf,(list,tuple)): vf=vf[0]
    if vf: VF=vf
    VHW=rig.get('vehicle_half_width',0.525) or 0.525
    THW=rig.get('trailer_half_width',0.475) or 0.475
    for nm in ('direct','periphery'):
        vw=views.get(nm)
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            if d>8.5: continue
            wp=tw(ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b)))
            MAP[(round(wp[0]*10),round(wp[1]*10))]=wp
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        e=rig['eye'];b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        wp=tw(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
        w=1.0/max(d,1.0);k=Cw*0.97
        C=[(C[0]*k+wp[0]*w)/(k+w),(C[1]*k+wp[1]*w)/(k+w)];Cw=k+w
    t=obs['t'];hd=obs.get('head') or {}
    gz=hd.get('gaze_deg',0)
    if glancing:
        look=45
        if abs(gz-45)<4 and hd.get('settled'):
            gdw+=1
            if gdw>=4: glancing=False;gl_next=t+6.0
    else:
        look=-168
        if t>gl_next: glancing=True;gdw=0
    phi=obs['hitch_deg']
    thT=TH+math.radians(rig['trailer_heading_deg'])
    state=(X,Y,TH,thT)
    H=tw(*rig['hitch'])
    A=(H[0]-0.85*math.cos(thT),H[1]-0.85*math.sin(thT))
    ux=math.cos(AX);uy=math.sin(AX);nx=-uy;ny=ux
    e=(A[0]-C[0])*nx+(A[1]-C[1])*ny
    sa=(C[0]-A[0])*ux+(C[1]-A[1])*uy
    kk=0.6 if sa>1.2 else 0.3
    bd=AX-clamp(kk*e,-0.6,0.6)
    pb=thT+math.pi
    a=math.degrees(wrap(bd-pb))
    phid=clamp(-1.5*a,-40,40)
    pr=math.radians(phi)
    deq=math.degrees(math.atan(1.25*math.sin(pr)/(0.85+0.3*math.cos(pr))))
    sdes=clamp(deq+1.3*(phi-phid),-45,45)
    near=[p for p in MAP.values() if (p[0]-X)**2+(p[1]-Y)**2<20]
