        if best[2]<0.05 and best[2]<=d0+0.005:
            mode='FWD';fs=(X,Y);print('rev blocked mc',round(best[2],2))
        else:
            spd=-0.35
            if best[2]<0.2 or abs(phi)>30: spd=-0.25
            if glancing: spd=-0.2
            if t-lastp>2.0:
                lastp=t
                print('R t%.1f X%.2f Y%.2f TH%.0f thT%.0f phi%.0f e%.2f sa%.1f sdes%.0f s%d mc%.2f d0%.2f C%.1f,%.1f'%(t,X,Y,math.degrees(TH),math.degrees(thT),phi,e,sa,sdes,best[1],best[2],d0,C[0],C[1]))
            return (best[1],spd,look)
    fdes=clamp(-0.8*phi,-35,35)
