AX=math.radians(-138)
mode='REV';fs=(0.0,0.0);lastp=-10.0
VF=1.55;VHW=0.525;THW=0.475
gl_next=0.0;glancing=True;gdw=0
for i in range(46):
    x=-2.0+i*0.1
    MAP[('s',i)]=(x,0.70-0.08*x)

def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def tw(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)
def clamp(v,a,b):
    return max(a,min(b,v))

def sim(x,y,th,thT,vs,sd,dist,n=4):
    ds=dist/n;tn=math.tan(math.radians(sd));out=[]
    for k in range(n):
        v=vs*ds;yaw=v*tn/1.25
        hvx=v*math.cos(th)+0.3*yaw*math.sin(th)
        hvy=v*math.sin(th)-0.3*yaw*math.cos(th)
        thT+=(-hvx*math.sin(thT)+hvy*math.cos(thT))/0.85
        thm=th+yaw/2
        x+=v*math.cos(thm);y+=v*math.sin(thm);th+=yaw
        out.append((x,y,th,thT))
    return out

def corners(x,y,th,thT):
    c=math.cos(th);s=math.sin(th)
