def clamp(v,a,b): return max(a,min(b,v))
def wrap(a): return (a+math.pi)%(2*math.pi)-math.pi
def tw(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py,Y+s*px+c*py)

def sim(x,y,th,thT,vs,sd,dist,n=5):
    ds=dist/n;tn=math.tan(math.radians(sd));out=[]
    for k in range(n):
        v=vs*ds;yaw=v*tn/1.25
        hvx=v*math.cos(th)+0.3*yaw*math.sin(th)
        hvy=v*math.sin(th)-0.3*yaw*math.cos(th)
        thT+=(-hvx*math.sin(thT)+hvy*math.cos(thT))/0.85
        thm=th+yaw/2
        x+=v*math.cos(thm);y+=v*math.sin(thm);th+=yaw
        out.append((x,y,th,thT))
    return out

def corners(st):
    x,y,th,thT=st
    c=math.cos(th);s=math.sin(th)
    def w(px,py): return (x+c*px-s*py,y+s*px+c*py)
    pts=[w(VF,VHW),w(VF,-VHW),w(VF,0),w(VF-0.9,VHW),w(VF-0.9,-VHW),w(VF-1.8,VHW),w(VF-1.8,-VHW)]
    hx,hy=w(-0.3,0)
    ct=math.cos(thT);sn=math.sin(thT)
    ax=hx-0.85*ct;ay=hy-0.85*sn
    for l in (0.55,-0.45):
        for sd in (THW,-THW):
            pts.append((ax+l*ct-sd*sn,ay+l*sn+sd*ct))
    pts.append((ax-0.45*ct,ay-0.45*sn))
    return pts

def clear(st,near):
    m=81.0
    for c in corners(st):
        for p in near:
            d=(p[0]-c[0])**2+(p[1]-c[1])**2
            if d<m: m=d
    return math.sqrt(m)

def cartinfo(st,near):
    x,y,th,thT=st
    hx=x-0.3*math.cos(th);hy=y-0.3*math.sin(th)
    ct=math.cos(thT);sn=math.sin(thT)
    rx0=hx-1.3*ct;ry0=hy-1.3*sn
