    global X,Y,TH,mode,fs,lastp,stuck,gl_next,gl_state,gl_t,ls
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion'];v=m['v_mps'];st=math.radians(obs['steer_deg'])
    th0=TH;TH+=v*math.tan(st)/1.25*dt;thm=(th0+TH)/2
    X+=v*math.cos(thm)*dt;Y+=v*math.sin(thm)*dt
    rig=obs['rig'];views=obs.get('views') or {};t=obs['t']
