            elif t-gl_t>0.25: gl_state=0;gl_next=t+3.0;ls+=1
    else:
        look=-160 if ls%2==0 else 155
    thT=TH-math.radians(phi)
    R=tw(*rig['trailer_rear'])
    pb=thT+math.pi
