    nlx=-math.sin(thT);nly=math.cos(thT)
    Lm=None;Rm=None;Lb=9.0
    for p in near:
        rx=p[0]-R[0];ry=p[1]-R[1]
        s=rx*bx+ry*by;l=rx*nlx+ry*nly
        if -1.2<s<1.5:
            if l>0: Lm=l if Lm is None else min(Lm,l)
            else: Rm=-l if Rm is None else min(Rm,-l)
        if s>0 and abs(l)<0.4: Lb=min(Lb,s)
    if Lm is not None and Rm is not None: off=(Lm-Rm)/2
