        mode='F';fs=(X,Y);stuck=0.0;print('->F t%.1f phi%.0f %s cfl%.2f cfr%.2f'%(t,phi,st_,cfl,cfr))
        return (clamp(-0.8*phi,-30,30),0.25,20)
    spd=-0.15
