    if t-lastp>1.5:
        lastp=t;print('R t%.1f phi%.0f phid%.0f off%.2f Lm%s Rm%s st%.0f cfl%.2f cfr%.2f Lb%.1f'%(t,phi,phid,off,None if Lm is None else round(Lm,2),None if Rm is None else round(Rm,2),steer,cfl,cfr,Lb))
