import math
L=3.9;A=0.35;LT=10.2
X=0.0;Y=0.0;TH=math.radians(13)
last_t=None
mode='fwd'
grid={}
corners={}
hdes_f=0.0
W0=-0.5
sweep_t=None
touch0=None
tick=0
GAZES=[-41,-72,-120,53,120,-41]

def wrap(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def clamp(v,a,b):
    return max(a,min(b,v))
def tow(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return X+px*c-py*s, Y+px*s+py*c
def tov(wx,wy):
    dx=wx-X;dy=wy-Y;c=math.cos(TH);s=math.sin(TH)
    return dx*c+dy*s, -dx*s+dy*c

def control(obs):
    global X,Y,TH,last_t,mode,hdes_f,sweep_t,touch0,tick
    tick+=1
    t=obs['t']
    dt=0.0 if last_t is None else max(0.0,t-last_t)
    last_t=t
    v=obs['motion']['v_mps']
    st=math.radians(obs['steer_deg'])
    TH+=v*math.tan(st)/L*dt
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt
    h=obs['hitch_deg']
    rig=obs['rig']
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]) or []:
            b=math.radians(w[0]);d=w[1]
            wx,wy=tow(ox+d*math.cos(b),oy+d*math.sin(b))
            grid[(round(wx),round(wy))]=name[:2]
        for c in vw.get('target_corners',[]) or []:
            try:
                b=math.radians(c[0]);d=c[1]
                wx,wy=tow(ox+d*math.cos(b),oy+d*math.sin(b))
                corners[(round(wx*2)/2,round(wy*2)/2)]=name[:2]
            except Exception:
                pass
    touches=obs['counters']['touches']
    if touch0 is None: touch0=touches
    rx,ry=rig['trailer_rear']
    RX,RY=tow(rx,ry)
    if touches>touch0 and mode in ('fwd','rev'):
        mode='hold'
        print('TOUCH t%.1f X%.1f Y%.1f TH%.0f h%.0f rear(%.1f,%.1f)'%(t,X,Y,math.degrees(TH),h,RX,RY))
        wake('touch')
    if mode=='rev' and abs(h)>45:
        mode='hold';print('big hitch',h);wake('hitch>45')
    if tick%30==0:
        print('%s t%.0f X%.1f Y%.1f TH%.0f h%.0f hd%.0f rear(%.1f,%.1f)'%(mode,t,X,Y,math.degrees(TH),h,hdes_f,RX,RY))
    if mode=='fwd':
        if X>=13.0:
            mode='rev'
        else:
            Ld=8.0
            dx,dy=tov(X+Ld,W0)
            a=math.atan2(dy,dx)
            steer=clamp(math.degrees(math.atan(2*L*math.sin(a)/Ld)),-30,30)
            return (steer,1.8,0)
    if mode=='rev':
        if RX<=-13.5:
            mode='sweep';sweep_t=None
        else:
            pr=math.radians(rig['trailer_heading_deg'])
            tf=TH+pr
            tback=tf+math.pi
            PX,PY=tow(rx+1.9*math.cos(pr),ry+1.9*math.sin(pr))
            e=PY-W0
            psi_des=math.pi+clamp(math.atan(e/7.0),-0.4,0.4)
            eh=math.degrees(wrap(psi_des-tback))
