import math
L=3.9;A=0.35;LT=10.2;HW=1.275;D0=1.9
mode='fwd';dist=0.0;last_t=None;hdes=None;touch0=None;tick=0;fl=6.0;dl_f=0.0

def clamp(v,a,b):
    return max(a,min(b,v))
def pts_of(vw):
    ox,oy=vw['origin'];out=[]
    for w in vw.get('walls') or []:
        b=math.radians(w[0]);d=w[1]
        out.append((ox+d*math.cos(b),oy+d*math.sin(b)))
    return out

def control(obs):
    global mode,dist,last_t,hdes,touch0,tick,fl,dl_f
    tick+=1
    t=obs['t']
    dt=0.0 if last_t is None else max(0.0,t-last_t)
    last_t=t
    v=obs['motion']['v_mps']
    dist+=abs(v)*dt
    h=obs['hitch_deg']
    rig=obs['rig']
    views=obs.get('views') or {}
    touches=obs['counters']['touches']
    if touch0 is None: touch0=touches
    if mode=='rev':
        trig=None
        if touches>touch0: trig='touch'
        elif obs.get('status')=='JACKKNIFED' or abs(h)>50: trig='fold'
        if trig:
            mode='fwd';dist=0.0;fl=2.5 if trig=='touch' else 4.0
            print('fwd',trig,'t%.1f h%.0f'%(t,h))
            try: wake('%s t=%.1f h=%.1f'%(trig,t,h))
            except Exception: pass
    touch0=touches
    if mode=='hold':
        return (obs['steer_deg'],0,-41)
    if mode=='fwd':
        front=rig['vehicle_front'];hw=rig['vehicle_half_width']
        blk=False
        for nm in ('direct','periphery'):
            vw=views.get(nm)
            if vw:
                for (x,y) in pts_of(vw):
                    if front-0.5<x<front+2.0 and abs(y)<hw+0.6: blk=True
        if dist>=fl or blk or (fl<5 and abs(h)<6 and dist>1.5):
            mode='rev';hdes=h
            print('rev start t%.1f h%.0f dist%.1f blk%s'%(t,h,dist,blk))
        else:
            if fl>=5: steer=clamp(1.5*(20-h),-35,35)
            else: steer=clamp(-1.0*h,-35,35)
            return (steer,1.0,0)
    if hdes is None: hdes=h
    rx,ry=rig['trailer_rear']
    bb=math.radians(rig['trailer_heading_deg']+180.0)
    cb=math.cos(bb);sb=math.sin(bb)
    cam=views.get('camera')
    spd=-0.6
    info='-'
    if cam:
        Lp=[];Rp=[];fr=[]
        for (x,y) in pts_of(cam):
            dx=x-rx;dy=y-ry
            u=dx*cb+dy*sb
            wl=dx*sb-dy*cb
            if -1<u<8 and 0.3<wl<5: Lp.append((u,wl))
            if -1<u<6 and -5<wl<-0.3: Rp.append((u,-wl))
            if 0<u<2.5 and abs(wl)<HW+0.2: fr.append(u)
        dl=None
        if len(Lp)>=3:
            us=[p[0] for p in Lp];ws=[p[1] for p in Lp]
            if max(us)-min(us)>1.0:
                n=len(Lp);mu=sum(us)/n;mw=sum(ws)/n
                sxx=sum((a-mu)**2 for a in us);sxy=sum((a-mu)*(b-mw) for a,b in Lp)
                b=sxy/sxx;a=mw-b*mu
                off=a+1.5*b
                dl=math.atan(b)+math.atan((off-D0)/6.0)
                info='b%.2f off%.2f'%(b,off)
        if Rp:
            mr=min(w for u,w in Rp)
            if mr<HW+0.7:
                dl=(dl if dl is not None else 0.0)+(HW+0.7-mr)/4.0
            info+=' mr%.1f'%mr
        if dl is not None:
            dl=clamp(dl,-0.5,0.5)
            dl_f=dl_f+0.3*(dl-dl_f)
        else:
            dl_f*=0.98
        near=[w for u,w in Lp if u<1.5]+[w for u,w in Rp if u<1.5]
        if near and min(near)<HW+0.4: spd=-0.3
        if fr and min(fr)<1.2:
            mode='hold';print('end wall t%.1f'%t)
            try: wake('wall close behind trailer')
            except Exception: pass
            return (obs['steer_deg'],0,-41)
    hd=clamp(1.5*math.degrees(dl_f),-40,40)
    hdes=hdes+clamp(hd-hdes,-1.5,1.5)
    hr=math.radians(hdes)
    deq=math.degrees(math.atan(L*math.sin(hr)/(LT-A*math.cos(hr))))
    steer=clamp(deq+1.5*(h-hdes),-42,42)
    if abs(h)>25: spd=max(spd,-0.5)
    if tick%20==0:
        print('t%.0f h%.0f hd%.0f dl%.0f %s'%(t,h,hdes,math.degrees(dl_f),info))
    return (steer,spd,-41)

