        if trig:
            mode='hold'
            print('stop',trig,'t%.1f h%.0f X%.1f Y%.1f TH%.0f'%(t,h,X,Y,math.degrees(TH)))
            try: wake('%s t=%.1f h=%.1f'%(trig,t,h))
            except Exception: pass
    touch0=touches
    if mode=='hold':
        return (obs['steer_deg'],0,-41)
    if mode=='fwd':
        if v>0: dist+=v*dt
