            wl=dx*sb-dy*cb
            if 0<u<1.0 and abs(wl)<HW+0.1: fr.append(u)
            if -1<u<3.5:
                if wl>0: ml=min(ml,wl)
                else: mr=min(mr,-wl)
        if ml<HW+0.7: psi+=clamp((HW+0.7-ml)/2.5,0,0.3)
        if mr<HW+0.7: psi-=clamp((HW+0.7-mr)/2.5,0,0.3)
        if min(ml,mr)<HW+0.35: spd=-0.3
        info='ml%.1f mr%.1f'%(ml,mr)
        if fr:
            mode='hold';print('end wall t%.1f %s rear(%.1f,%.1f)'%(t,info,RX,RY))
            try: wake('wall close behind trailer')
            except Exception: pass
            return (obs['steer_deg'],0,-41)
    eh=math.degrees(wrap(psi-tback))
    hd=clamp(-1.4*eh,-32,32)
    hdes=hdes+clamp(hd-hdes,-2.0,2.0)
    hr=math.radians(hdes)
    deq=math.degrees(math.atan(L*math.sin(hr)/(LT-A*math.cos(hr))))
    steer=clamp(deq+1.5*(h-hdes),-42,42)
    if abs(h)>25: spd=max(spd,-0.5)
    if tick%20==0:
        print('t%.0f h%.0f hd%.0f el%.1f eh%.0f %s rear(%.1f,%.1f) tb%.0f'%(t,h,hdes,el,eh,info,RX,RY,math.degrees(tback)))
    return (steer,spd,-41)

