import math
L=3.9;A=0.35;LT=10.2;HW=1.275;D0=2.1
mode='fwd';dist=0.0;last_t=None;hdes=None;touch0=None;tick=0;dl_f=None

def clamp(v,a,b):
    return max(a,min(b,v))
def pts_of(vw):
    ox,oy=vw['origin'];out=[]
    for w in vw.get('walls') or []:
        b=math.radians(w[0]);d=w[1]
        out.append((ox+d*math.cos(b),oy+d*math.sin(b)))
    return out

def control(obs):
    global mode,dist,last_t,hdes,touch0,tick,dl_f
    tick+=1
    t=obs['t']
    dt=0.0 if last_t is None else max(0.0,t-last_t)
    last_t=t
    v=obs['motion']['v_mps']
    h=obs['hitch_deg']
    rig=obs['rig']
    views=obs.get('views') or {}
    touches=obs['counters']['touches']
    if touch0 is None: touch0=touches
    if mode=='rev':
        trig=None
        if touches>touch0: trig='touch'
        elif obs.get('status')=='JACKKNIFED' or abs(h)>45: trig='fold'
        if trig:
            mode='hold';print('stop',trig,'t%.1f h%.0f'%(t,h))
            try: wake('%s t=%.1f h=%.1f'%(trig,t,h))
            except Exception: pass
    touch0=touches
    if mode=='hold':
        return (obs['steer_deg'],0,-41)
    if mode=='fwd':
        if v>0: dist+=v*dt
        if dist>=1.5:
            mode='rev';hdes=h
            print('rev start t%.1f h%.0f'%(t,h))
        else:
            return (15.0,0.8,-41)
    if hdes is None: hdes=h
    rx,ry=rig['trailer_rear']
    bb=math.radians(rig['trailer_heading_deg']+180.0)
    cb=math.cos(bb);sb=math.sin(bb)
    cam=views.get('camera')
    spd=-0.5
    info='-'
    if cam:
        Lp=[];Rp=[];fr=[]
        for (x,y) in pts_of(cam):
            dx=x-rx;dy=y-ry
            u=dx*cb+dy*sb
            wl=dx*sb-dy*cb
            if -1<u<5.5 and 0.2<wl<4: Lp.append((u,wl))
            if -1<u<4 and -4<wl<-0.2: Rp.append((u,-wl))
            if 0<u<0.8 and abs(wl)<HW-0.1: fr.append(u)
        dl=None
        if len(Lp)>=3:
            us=[p[0] for p in Lp];ws=[p[1] for p in Lp]
            if max(us)-min(us)>1.0:
                n=len(Lp);mu=sum(us)/n;mw=sum(ws)/n
                sxx=sum((a-mu)**2 for a in us);sxy=sum((a-mu)*(b-mw) for a,b in Lp)
                b=sxy/sxx;a=mw-b*mu
                off=a+1.0*b
                dl=math.atan(b)+math.atan((off-D0)/5.0)
                info='b%.2f off%.2f n%d'%(b,off,n)
        if Rp:
            mr=min(w for u,w in Rp)
            if mr<HW+0.6:
                dl=(dl if dl is not None else 0.0)+(HW+0.6-mr)/4.0
            info+=' mr%.1f'%mr
        if dl is not None:
            dl=clamp(dl,-0.4,0.4)
            if dl_f is None: dl_f=dl
            dl_f=dl_f+0.3*(dl-dl_f)
        elif dl_f is not None:
            dl_f*=0.97
        near=[w for u,w in Lp if u<1.5]+[w for u,w in Rp if u<1.5]
        if near and min(near)<HW+0.3: spd=-0.3
        if fr:
            mode='hold';print('end wall t%.1f %s'%(t,info))
            try: wake('wall close behind trailer')
            except Exception: pass
            return (obs['steer_deg'],0,-41)
    dd=dl_f if dl_f is not None else 0.0
    hd=clamp(1.5*math.degrees(dd),-25,25)
    hdes=hdes+clamp(hd-hdes,-1.5,1.5)
    hr=math.radians(hdes)
    deq=math.degrees(math.atan(L*math.sin(hr)/(LT-A*math.cos(hr))))
    steer=clamp(deq+1.5*(h-hdes),-42,42)
    if tick%15==0:
        print('t%.0f h%.0f hd%.0f dl%.0f %s'%(t,h,hdes,math.degrees(dd),info))
    return (steer,spd,-41)

